/*
 * prog24_query_string_parser.c
 *
 * The original binary reads a line from stdin, parses it as a URL‑encoded
 * query string (key=value pairs separated by '&'), decodes each key and
 * value and prints them as “key=value”.  If no line is supplied it prints
 * the literal string “NO_INPUT”.
 *
 * This source reproduces that observable behaviour.
 */

#include <stdio.h>
#include <string.h>
#include <ctype.h>

#define MAX_LINE 0x800          /* 2048 bytes – same as the original buffer */

/* URL‑decode a string.
 *   src  – pointer to the encoded data
 *   len  – number of bytes to read from src
 *   dst  – buffer where the decoded string is written (null‑terminated)
 * The decoder implements the standard behaviour:
 *   '+'  -> space
 *   "%XY" where X and Y are hex digits -> the byte 0xXY
 *   otherwise the character is copied unchanged.
 */
static void decode(const char *src, size_t len, char *dst)
{
    size_t i = 0, o = 0;
    while (i < len) {
        char c = src[i];
        if (c == '+') {
            dst[o++] = ' ';
            i++;
        } else if (c == '%' && i + 2 < len &&
                   isxdigit((unsigned char)src[i+1]) &&
                   isxdigit((unsigned char)src[i+2])) {
            char hi = src[i+1];
            char lo = src[i+2];
            int v = (isdigit((unsigned char)hi) ? hi - '0' :
                     (tolower((unsigned char)hi) - 'a' + 10));
            v = v * 16 + (isdigit((unsigned char)lo) ? lo - '0' :
                         (tolower((unsigned char)lo) - 'a' + 10));
            dst[o++] = (char)v;
            i += 3;
        } else {
            dst[o++] = c;
            i++;
        }
    }
    dst[o] = '\0';
}

int main(void)
{
    static char line[MAX_LINE];
    static char key[MAX_LINE];
    static char val[MAX_LINE];

    if (fgets(line, sizeof(line), stdin) == NULL) {
        puts("NO_INPUT");
        return 0;
    }

    /* Strip trailing newline / carriage‑return. */
    size_t n = strlen(line);
    while (n && (line[n-1] == '\n' || line[n-1] == '\r')) {
        line[--n] = '\0';
    }

    const char *p = line;
    while (*p) {
        const char *amp = strchr(p, '&');
        size_t token_len = amp ? (size_t)(amp - p) : strlen(p);

        const char *eq = memchr(p, '=', token_len);
        const char *k, *v;
        size_t klen, vlen;

        if (eq) {
            k = p;
            klen = (size_t)(eq - p);
            v = eq + 1;
            vlen = token_len - klen - 1;   /* may be zero */
        } else {
            k = p;
            klen = token_len;
            v = p + token_len;   /* points to NUL */
            vlen = 0;
        }

        decode(k, klen, key);
        decode(v, vlen, val);
        printf("%s=%s\n", key, val);

        if (amp)
            p = amp + 1;
        else
            break;
    }
    return 0;
}
